S NULL AND \"IntegrityEvidenceDigest\" IS NULL AND \"IntegrityUnavailableAtUtc\" IS NULL AND \"OutcomeUnknownAtUtc\" IS NOT NULL AND \"ServerStreamCompletedAtUtc\" IS NULL AND \"VerifiedByteCount\" IS NULL AND \"VerifiedPackageCiphertextDigest\" IS NULL AND \"DeliveryReceiptDigest\" IS NULL AND \"ExpiredAtUtc\" IS NULL) OR (\"State\"='ServerStreamCompleted' AND \"StreamAttemptCount\">0 AND \"DeliveryFence\">0 AND \"StreamStartedAtUtc\" IS NOT NULL AND \"StreamLeaseExpiresAtUtc\"=\"StreamStartedAtUtc\"+interval '35 minutes' AND \"StreamApiKeyId\" IS NOT NULL AND \"StreamPrincipalId\" IS NOT NULL AND \"StreamCorrelationDigest\" IS NOT NULL AND \"InterruptionKind\" IS NULL AND \"InterruptionEvidenceDigest\" IS NULL AND \"InterruptedAtUtc\" IS NULL AND \"IntegrityFailureKind\" IS NULL AND \"IntegrityEvidenceDigest\" IS NULL AND \"IntegrityUnavailableAtUtc\" IS NULL AND \"OutcomeUnknownAtUtc\" IS NULL AND \"ServerStreamCompletedAtUtc\" IS NOT NULL AND \"VerifiedByteCount\"=\"EncryptedPackageLength\" AND \"VerifiedPackageCiphertextDigest\"=\"PackageCiphertextDigest\" AND \"DeliveryReceiptDigest\" IS NOT NULL AND \"ExpiredAtUtc\" IS NULL) OR (\"State\"='Expired' AND \"ExpiredAtUtc\" IS NOT NULL AND \"IntegrityFailureKind\" IS NULL AND \"IntegrityEvidenceDigest\" IS NULL AND \"IntegrityUnavailableAtUtc\" IS NULL AND \"OutcomeUnknownAtUtc\" IS NULL AND \"ServerStreamCompletedAtUtc\" IS NULL AND \"VerifiedByteCount\" IS NULL AND \"VerifiedPackageCiphertextDigest\" IS NULL AND \"DeliveryReceiptDigest\" IS NULL AND ((\"StreamAttemptCount\"=0 AND \"DeliveryFence\"=0 AND \"StreamStartedAtUtc\" IS NULL AND \"StreamLeaseExpiresAtUtc\" IS NULL AND \"StreamApiKeyId\" IS NULL AND \"StreamPrincipalId\" IS NULL AND \"StreamCorrelationDigest\" IS NULL AND \"InterruptionKind\" IS NULL AND \"InterruptionEvidenceDigest\" IS NULL AND \"InterruptedAtUtc\" IS NULL) OR (\"StreamAttemptCount\">0 AND \"DeliveryFence\">0 AND \"StreamStartedAtUtc\" IS NOT NULL AND \"StreamLeaseExpiresAtUtc\"=\"Stre